def pair(x, y):
    return lambda m: m(x, y)
def head(z):
    return z(lambda p, q: p)
def tail(z):
    return z(lambda p, q: q)

def llist_ref(items, n):
    return head(items) if n == 0 else llist_ref(tail(items), n - 1)
def map(fun, items):
    if is_none(items):
        return None
    else:
        return pair(fun(head(items)), map(fun, tail(items)))
def scale_llist(items, factor):
    return map(lambda x: x * factor, items)
def add_llists(list1, list2):
    if is_none(list1):
        return list2
    elif is_none(list2):
        return list1
    else:
        return pair(head(list1) + head(list2),
                    add_llists(tail(list1), tail(list2)))
ones = pair(1, ones)
integers = pair(1, add_llists(ones, integers))
